CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(120) NOT NULL, role VARCHAR(20) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE accounts (id BIGINT AUTO_INCREMENT PRIMARY KEY, account_number VARCHAR(34) NOT NULL UNIQUE, user_id BIGINT NOT NULL, account_type VARCHAR(30) NOT NULL, balance DECIMAL(19,2) NOT NULL, currency CHAR(3) NOT NULL, status VARCHAR(20) NOT NULL, version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_account_user FOREIGN KEY (user_id) REFERENCES users(id), INDEX ix_accounts_user (user_id));
CREATE TABLE transactions (id BIGINT AUTO_INCREMENT PRIMARY KEY, sender_account_id BIGINT NULL, recipient_account_id BIGINT NULL, initiated_by_user_id BIGINT NOT NULL, type VARCHAR(20) NOT NULL, amount DECIMAL(19,2) NOT NULL, status VARCHAR(20) NOT NULL, risk_level VARCHAR(20) NOT NULL, risk_score INT NOT NULL, description VARCHAR(255), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_tx_sender FOREIGN KEY (sender_account_id) REFERENCES accounts(id), CONSTRAINT fk_tx_recipient FOREIGN KEY (recipient_account_id) REFERENCES accounts(id), CONSTRAINT fk_tx_user FOREIGN KEY (initiated_by_user_id) REFERENCES users(id), INDEX ix_tx_user_created (initiated_by_user_id, created_at), INDEX ix_tx_risk (risk_level));
CREATE TABLE fraud_analyses (id BIGINT AUTO_INCREMENT PRIMARY KEY, transaction_id BIGINT NOT NULL UNIQUE, risk_score INT NOT NULL, risk_level VARCHAR(20) NOT NULL, action VARCHAR(20) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_analysis_tx FOREIGN KEY (transaction_id) REFERENCES transactions(id));
CREATE TABLE fraud_rule_results (id BIGINT AUTO_INCREMENT PRIMARY KEY, fraud_analysis_id BIGINT NOT NULL, rule_name VARCHAR(80) NOT NULL, reason VARCHAR(500) NOT NULL, severity VARCHAR(20) NOT NULL, score_contribution INT NOT NULL, CONSTRAINT fk_result_analysis FOREIGN KEY (fraud_analysis_id) REFERENCES fraud_analyses(id));
